INSERT INTO course (course_id,course_name,course_desc,is_delete,is_active,created_by,created_date,modified_by,modified_date,ip_address) VALUES ('25','UPSC','Studying for the UPSC (Union Public Service Commission) exam is a rigorous process that requires comprehensive preparation. The UPSC exam consists of three stages: Preliminary Examination (Prelims), Main Examination (Mains), and Personality Test (Interview). It covers a wide range of subjects, including General Studies, Optional Subjects, and Essay Writing.','0','1','1','2023-09-14 11:43:47',NULL,'2023-09-14 06:13:47',NULL);
